import {BookOpen,Library,Search,Sparkles,Settings,Plus,Upload,ArrowUpRight,ChevronLeft,ChevronRight,ChevronDown,X,PanelRightClose,PanelRightOpen,Highlighter,Mic,Square,Play,FileText,MoreHorizontal,Sun,Moon,Download,Check,Quote,Send,Trash2,Edit3,Volume2,Tag,ArrowLeft,Folder,Command,ZoomIn,ZoomOut,Eye,EyeOff,BookMarked,LoaderCircle,ShieldCheck,Maximize2,Minimize2} from 'lucide-react';
