const date=d=>new Date(d).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});
const splitTags=s=>s.split(',').map(t=>t.trim()).filter(Boolean);
function DownloadLink({route,children,...props}){return <a {...props} href={browserStorage?'#':'/api'+route} onClick={browserStorage?e=>{e.preventDefault();downloadResource(route,{chooseFile:false}).catch(e=>alert(e.message));}:undefined}>{children}</a>;}
function SavedAudio({id,file}){const [url,setUrl]=useState(''),[error,setError]=useState('');useEffect(()=>{let disposed=false,current;audioSource(id).then(value=>{current=value;if(disposed&&value.startsWith('blob:'))URL.revokeObjectURL(value);else if(!disposed)setUrl(value);}).catch(e=>{if(!disposed)setError(e.message);});return()=>{disposed=true;if(current?.startsWith('blob:'))URL.revokeObjectURL(current);};},[id,file]);return error?<p className="inline-error">{error}</p>:<audio controls preload="metadata" src={url||undefined}/>;}
function IconButton({icon:Icon,title,onClick,active,disabled,...rest}){return <button className={'icon-button '+(active?'active':'')} title={title} aria-label={title} onClick={onClick} disabled={disabled} {...rest}><Icon size={18}/></button>;}
