  const jump=s=>{const n=notes.find(n=>n.id===s.id)||{...s,rects:s.rects||[],anchor:s.anchor||{}};openDoc(s.docId,s.page||1,n);};
  const addNote=(selection=null,audio=false)=>{if(!current)return;setEditor({id:null,docId:current.id,page:null,quote:'',comment:'',transcript:'',rects:[],anchor:{},tags:[],color:'amber',highlight:false,...selection,audioMode:audio});};
  useEffect(()=>{const handler=e=>{if(e.key==='Escape'){setModal(null);}if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();setView('retrieve');}if((e.ctrlKey||e.metaKey)&&e.shiftKey&&e.key.toLowerCase()==='n'){e.preventDefault();if(current)addNote();}};window.addEventListener('keydown',handler);return()=>window.removeEventListener('keydown',handler);},[current]);
  async function upload(files){if(!files?.length)return;setBusy(true);try{for(const f of files){const form=new FormData();form.append('pdf',f);const d=await api('/documents',{method:'POST',body:form});setDocs(ds=>[d,...ds]);openDoc(d.id);}setToast('PDF imported. Review its citation details when you are ready.');}catch(e){setError(e.message);}finally{setBusy(false);if(uploadRef.current)uploadRef.current.value='';}}
  // Save the thought before uploading or transcribing its recording.
