function Reader({doc,notes,position,onPosition,onAdd,onHighlight,highlightColor,expanded,setExpanded,onEdit,onDelete,onSelectNote,focus,sidebar,setSidebar,showAnnotations,setShowAnnotations,onJump,onMetadata,onCitation,onCiteNote,onBack,onError,onTranscribed}){
  const [pdf,setPdf]=useState(null),[selection,setSelection]=useState(null),[pages,setPages]=useState([]),[find,setFind]=useState(''),[findOpen,setFindOpen]=useState(false),[pageInput,setPageInput]=useState('1'),[navigation,setNavigation]=useState(null);
  const findRef=useRef(),navigationId=useRef(0),onPositionRef=useRef(onPosition);onPositionRef.current=onPosition;
  const page=Math.max(1,Math.min(doc.pageCount,position.page||1)),zoom=position.zoom||1;
  useEffect(()=>{setPageInput(String(page));},[page]);
  useEffect(()=>{
    let stopped=false,task;
    api('/documents/'+doc.id+'/pages').then(value=>{if(!stopped)setPages(value);}).catch(e=>{if(!stopped)onError(e.message);});
    documentSource(doc.id).then(source=>{if(stopped)return;task=pdfjs.getDocument({...source,isEvalSupported:false,cMapUrl:import.meta.env.BASE_URL+'pdf-assets/cmaps/',cMapPacked:true,standardFontDataUrl:import.meta.env.BASE_URL+'pdf-assets/standard_fonts/',wasmUrl:import.meta.env.BASE_URL+'pdf-assets/wasm/'});return task.promise;}).then(value=>{if(!stopped&&value)setPdf(value);}).catch(e=>{if(!stopped)onError('PDF could not be displayed: '+e.message);});
    return()=>{stopped=true;task?.destroy();};
  },[doc.id]);
  function goToPage(value){
    const target=Math.max(1,Math.min(doc.pageCount,Math.round(Number(value))||1));
    setSelection(null);setNavigation({page:target,id:++navigationId.current});
    onPositionRef.current({page:target,scroll:0,scrollRatio:0});
  }
  useEffect(()=>{
    const handler=e=>{
      if((e.ctrlKey||e.metaKey)&&e.key==='f'){e.preventDefault();setFindOpen(true);setTimeout(()=>findRef.current?.focus(),20);}
      if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;
      if(e.key==='ArrowRight'&&page<doc.pageCount)goToPage(page+1);
      if(e.key==='ArrowLeft'&&page>1)goToPage(page-1);
    };
    window.addEventListener('keydown',handler);return()=>window.removeEventListener('keydown',handler);
  },[page,doc.pageCount]);
  const matches=find.trim()?pages.filter(p=>p.text.toLowerCase().includes(find.trim().toLowerCase())):[];
  const choose=(audio=false)=>{const value=selection;setSelection(null);onAdd(value,audio);window.getSelection()?.removeAllRanges();};
  return <div className="reading-room">
    <div className="reader-heading"><button className="reader-title" onClick={onMetadata}><span>{doc.title}</span><ChevronDown size={15}/></button><div className="reader-actions">
      <button className="text-button" onClick={()=>onAdd()} aria-label="Add thought"><Plus size={15}/>Thought</button>
      <button className="text-button" onClick={onCitation}><Quote size={15}/>Cite</button>
      <IconButton icon={Search} title="Search within document (Ctrl+F)" onClick={()=>setFindOpen(!findOpen)}/>
      <IconButton icon={showAnnotations?Eye:EyeOff} title={showAnnotations?'Hide annotations':'Show annotations'} onClick={()=>setShowAnnotations(!showAnnotations)}/>
      <IconButton icon={sidebar?PanelRightClose:PanelRightOpen} title={sidebar?'Close thoughts sidebar':'Open thoughts sidebar'} aria-expanded={sidebar} onClick={()=>setSidebar(!sidebar)}/>
      <button className="reader-expand" title={expanded?'Exit expanded reading view':'Expand reading view'} aria-label={expanded?'Exit expanded reading view':'Expand reading view'} aria-pressed={expanded} onClick={()=>setExpanded(!expanded)}>{expanded?<Minimize2 size={16}/>:<Maximize2 size={16}/>}<span>{expanded?'Exit expanded view':'Expand'}</span></button>
    </div></div>
    <div className="reader-body"><section className="pdf-region">
      <div className="pdf-controls"><div className="page-controls">
        <IconButton icon={ChevronLeft} title="Previous page" disabled={page<=1} onClick={()=>goToPage(page-1)}/>
        <input aria-label="PDF page number" value={pageInput} onChange={e=>setPageInput(e.target.value)} onKeyDown={e=>{if(e.key==='Enter')e.currentTarget.blur();}} onBlur={()=>goToPage(pageInput)}/>
        <span>/ {doc.pageCount}</span><IconButton icon={ChevronRight} title="Next page" disabled={page>=doc.pageCount} onClick={()=>goToPage(page+1)}/>
        {pages[page-1]?.label&&<small>Printed: {pages[page-1].label}</small>}
      </div><div className="zoom-controls">
        <IconButton icon={ZoomOut} title="Zoom out" disabled={zoom<=.5} onClick={()=>onPosition({zoom:Math.max(.5,zoom-.1)})}/>
        <button onClick={()=>onPosition({zoom:1})} title="Fit page width">{Math.round(zoom*100)}%</button>
        <IconButton icon={ZoomIn} title="Zoom in" disabled={zoom>=2.5} onClick={()=>onPosition({zoom:Math.min(2.5,zoom+.1)})}/>
      </div></div>
      {findOpen&&<div className="find-panel"><label className="search-input"><Search size={16}/><input ref={findRef} placeholder="Find in this document…" value={find} onChange={e=>setFind(e.target.value)}/><IconButton icon={X} title="Close document search" onClick={()=>setFindOpen(false)}/></label>{find&&<div className="find-results">{matches.length?matches.slice(0,30).map(p=>{const start=p.text.toLowerCase().indexOf(find.trim().toLowerCase());return <button key={p.number} onClick={()=>{setFindOpen(false);onSelectNote({docId:doc.id,page:p.number,quote:p.text.slice(start,start+find.trim().length),rects:[]});}}><b>PDF {p.number}{p.label?' · printed '+p.label:''}</b><span>…{p.text.slice(Math.max(0,start-35),start+find.trim().length+70)}…</span></button>}):<p>No selectable text matches.</p>}</div>}</div>}
      {doc.scannedPages.includes(page)&&<div className="scan-notice"><FileText size={17}/>This page has no selectable text. It may be scanned. OCR is not included; you can still record or write a general document thought.</div>}
      {pdf?<ContinuousPDF pdf={pdf} doc={doc} pages={pages} position={position} navigation={navigation} focus={focus} notes={notes} showAnnotations={showAnnotations} onPosition={onPosition} onSelection={setSelection} onSelectNote={onSelectNote} onError={onError}/>:<div className="pdf-preparing"><LoaderCircle size={20} className="spin"/>Opening your paper…</div>}
      <footer className="reader-footer"><span><ShieldCheck size={13}/>Stored on this device</span><span>Scroll to keep reading · PDF page {page} of {doc.pageCount}{pages[page-1]?.label?' · printed '+pages[page-1].label:''}</span></footer>
    </section>
    {sidebar&&<aside className="notes-sidebar"><div className="notes-sidebar-title"><h2>Margin notes <small>{notes.length}</small></h2><IconButton icon={Plus} title="Add a general document thought" onClick={()=>onAdd()}/></div><p className="sidebar-subtitle">Your conversation with this paper.</p><div className="sidebar-notes">{notes.length?notes.slice().sort((a,b)=>(a.page||0)-(b.page||0)).map(n=><NoteCard key={n.id} note={n} doc={doc} selected={focus?.id===n.id} onJump={()=>onJump(n)} onCite={()=>onCiteNote(n)} onEdit={()=>onEdit(n)} onDelete={()=>onDelete(n)} onTranscribed={onTranscribed} onError={onError}/>):<div className="empty-notes"><Quote size={28}/><h3>A thought starts here.</h3><p>Select a passage and add your perspective. It will be waiting here when you return.</p><button className="secondary" onClick={()=>onAdd()}>Add a document thought</button></div>}</div><DownloadLink className="sidebar-export" route={'/export?docId='+doc.id}><Download size={15}/>Export this paper’s notes</DownloadLink></aside>}
    </div>
    {selection&&<SelectionToolbar selection={selection} color={highlightColor} onHighlight={async color=>{await onHighlight(selection,color);setSelection(null);window.getSelection()?.removeAllRanges();}} onThought={()=>choose()} onVoice={()=>choose(true)} onError={onError}/>}
  </div>;
}

function NoteCard({note:n,doc,onJump,onCite,onEdit,onDelete,selected,onTranscribed,onError}){const [busy,setBusy]=useState(false);return <article id={'note-'+n.id} className={'note-card '+(selected?'selected':'')}><div className="note-card-top"><button className={'page-chip '+n.color} onClick={onJump}>{n.page?(n.pageLabel?'Page '+n.pageLabel:'PDF page '+n.page):'Document thought'}</button><div><IconButton icon={Edit3} title="Edit thought" onClick={onEdit}/><IconButton icon={Trash2} title="Delete thought" onClick={onDelete}/></div></div>{doc&&<p className="note-doc-title">{doc.title}</p>}{n.page&&<div className="note-page-reference"><span><FileText size={12}/><strong>{pageReference(n)}</strong></span>{onCite&&<button className="text-button" onClick={onCite}><Quote size={12}/>Cite passage</button>}</div>}{n.quote&&<button className="quote-link" onClick={onJump}><blockquote>{n.quote}</blockquote></button>}{n.comment&&<div className="thought-text"><span className="content-label">MY THOUGHT</span><p>{n.comment}</p></div>}{n.audioFile&&<div className="audio-block"><SavedAudio id={n.id} file={n.audioFile}/>{!n.transcript&&<><p className="audio-status">Not transcribed · audio content is not searchable</p><button className="text-button" disabled={busy} onClick={async()=>{setBusy(true);try{const updated=await api('/annotations/'+n.id+'/transcribe',{method:'POST'});onTranscribed?.(updated);}catch(e){onError?.(e.message);}finally{setBusy(false);}}}>{busy?'Transcribing…':'Transcribe recording'}</button></>}</div>}{n.transcript&&<div className="transcript-block"><span className="content-label"><Mic size={12}/>MY TRANSCRIPT</span><p>{n.transcript}</p></div>}{n.tags.length>0&&<div className="card-tags">{n.tags.map(t=><span key={t}>#{t}</span>)}</div>}<div className="note-date">{date(n.createdAt)}{n.updatedAt!==n.createdAt&&' · edited'}</div></article>;}

function NoteEditor({note,doc,onClose,onSave,onDeleteAudio}){
  const [draft,setDraft]=useState({...note,highlight:isHighlighted(note)}),[tags,setTags]=useState(note.tags.join(', ')),[blob,setBlob]=useState(null),[preview,setPreview]=useState(''),[recording,setRecording]=useState(false),[error,setError]=useState(''),[busy,setBusy]=useState(false),[seconds,setSeconds]=useState(0),[acquiring,setAcquiring]=useState(false);
  const recorder=useRef(),stream=useRef(),chunks=useRef([]),started=useRef(),mounted=useRef(true);
  useEffect(()=>{mounted.current=true;return()=>{mounted.current=false;if(recorder.current?.state==='recording')recorder.current.stop();stream.current?.getTracks().forEach(t=>t.stop());};},[]);
  useEffect(()=>{if(note.id&&!draft.id)setDraft(d=>({...d,id:note.id}));},[note.id]);
  useEffect(()=>{if(!blob){setPreview('');return;}const url=URL.createObjectURL(blob);setPreview(url);return()=>URL.revokeObjectURL(url);},[blob]);
  useEffect(()=>{if(!recording)return;const t=setInterval(()=>setSeconds(Math.floor((Date.now()-started.current)/1000)),500);return()=>clearInterval(t);},[recording]);
  async function record(){setError('');setAcquiring(true);try{if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw new Error('Audio recording is not supported in this browser. Use a recent Chrome, Edge, or Firefox on HTTPS or localhost.');let expired=false,timer;const pending=navigator.mediaDevices.getUserMedia({audio:true});pending.then(media=>{if(expired||!mounted.current)media.getTracks().forEach(t=>t.stop());},()=>{});try{stream.current=await Promise.race([pending,new Promise((_,reject)=>{timer=setTimeout(()=>{expired=true;reject(new Error('Microphone permission is still pending. Check the browser permission prompt. If this embedded preview cannot grant access, open this site in Chrome or Edge.'));},20000);})]);}finally{clearTimeout(timer);}if(!mounted.current){stream.current?.getTracks().forEach(t=>t.stop());return;}const mime=['audio/webm;codecs=opus','audio/ogg;codecs=opus','audio/mp4'].find(t=>MediaRecorder.isTypeSupported(t));const r=new MediaRecorder(stream.current,mime?{mimeType:mime}:{});recorder.current=r;chunks.current=[];r.ondataavailable=e=>{if(e.data.size)chunks.current.push(e.data);};r.onstop=()=>{const b=new Blob(chunks.current,{type:r.mimeType});if(!b.size)setError('No audio was captured. Please record again.');else if(b.size>25*1024*1024)setError('Recording exceeds 25 MB. Please record a shorter thought.');else setBlob(b);stream.current?.getTracks().forEach(t=>t.stop());setRecording(false);};r.onerror=()=>{setError('Recording stopped unexpectedly. Please try again.');stream.current?.getTracks().forEach(t=>t.stop());setRecording(false);};started.current=Date.now();setSeconds(0);setRecording(true);r.start(500);}catch(e){stream.current?.getTracks().forEach(t=>t.stop());setError(e.name==='NotAllowedError'?'Microphone access was denied. Allow the microphone for this site in your browser’s site settings, then try again. You can still save a written thought.':e.name==='NotFoundError'?'No microphone was found. Connect one and try again.':e.message);}finally{if(mounted.current)setAcquiring(false);}}
  function close(){if(busy)return;if(recording||blob||draft.comment!==note.comment||draft.transcript!==note.transcript||draft.highlight!==isHighlighted(note)){if(!confirm('Discard this unsaved thought or recording?'))return;}onClose();}
  useEffect(()=>{const esc=e=>{if(e.key==='Escape'){e.preventDefault();close();}};const unload=e=>{if(recording||blob||draft.comment!==note.comment||draft.transcript!==note.transcript||draft.highlight!==isHighlighted(note)){e.preventDefault();e.returnValue='';}};window.addEventListener('keydown',esc);window.addEventListener('beforeunload',unload);return()=>{window.removeEventListener('keydown',esc);window.removeEventListener('beforeunload',unload);};},[recording,blob,draft,busy]);
  return <Modal title={note.id?'Revisit your thought':note.highlightOnly?'Keep this passage':'Capture a thought'} subtitle={doc.title+(note.page?' · '+pageReference(note):' · General document note')} onClose={close}><form onSubmit={async e=>{e.preventDefault();setBusy(true);setError('');try{const saved=await onSave({...draft,tags:splitTags(tags)},blob);setDraft(saved);}catch(e){setError(e.message);}finally{setBusy(false);}}}>
    {note.quote&&<div className="editor-quotation"><span className="content-label">AUTHOR’S WORDS</span><blockquote>{note.quote}</blockquote></div>}{note.page&&note.quote&&<div className="highlight-option"><label className="toggle-label"><input type="checkbox" checked={draft.highlight} onChange={e=>setDraft({...draft,highlight:e.target.checked})}/>Highlight passage</label><p>Your thought stays linked to this passage even without a highlight.</p></div>}<label className="field">Your thought<textarea autoFocus={!note.audioMode} rows={4} placeholder="What does this bring to mind?" value={draft.comment} onChange={e=>setDraft({...draft,comment:e.target.value})}/></label><div className="recorder"><div><Mic size={20}/><span><strong>Think out loud</strong><small>{recording?'Recording · '+seconds+' seconds':acquiring?'Waiting for microphone permission…':'Your original recording stays with this thought.'}</small></span></div>{recording?<button type="button" className="record-stop" onClick={()=>recorder.current.stop()}><Square size={14}/>Stop recording</button>:<button type="button" className="secondary" disabled={acquiring} onClick={record}><Mic size={15}/>{acquiring?'Waiting for microphone…':blob||note.audioFile?'Record again':'Record voice'}</button>}</div>{(preview||note.audioFile)&&<div className="audio-preview">{preview?<audio controls src={preview}/>:<SavedAudio id={note.id} file={note.audioFile}/>}<button type="button" className="text-button danger" onClick={async()=>{if(blob)setBlob(null);else if(confirm('Delete the saved original recording?')){try{await onDeleteAudio();}catch(e){setError(e.message);}}}}>Delete recording</button></div>}{(note.audioFile||blob||draft.transcript)&&<label className="field">Editable transcript <small>{note.originalTranscript?'Original provider transcript is preserved below.':'Optional. Untranscribed audio cannot be searched by its content.'}</small><textarea rows={3} placeholder="Type a transcript, or transcribe the saved recording later." value={draft.transcript||''} onChange={e=>setDraft({...draft,transcript:e.target.value})}/></label>}{note.originalTranscript&&<details className="original-transcript"><summary>Original provider transcript</summary><p>{note.originalTranscript}</p></details>}{note.transcriptHistory?.length>0&&<details className="original-transcript"><summary>Previous transcript versions ({note.transcriptHistory.length})</summary>{note.transcriptHistory.map((v,i)=><div key={i}><small>{date(v.savedAt)} · {v.reason}</small><p>{v.text}</p></div>)}</details>}<div className="editor-options"><label className="field">Tags<input value={tags} placeholder="evidence, methodology" onChange={e=>setTags(e.target.value)}/></label>{draft.highlight&&<fieldset className="color-picker"><legend>Highlight color</legend>{['amber','sage','rose','blue'].map(c=><button type="button" aria-label={c+' highlight'} aria-pressed={draft.color===c} className={'swatch '+c+(draft.color===c?' checked':'')} key={c} onClick={()=>setDraft({...draft,color:c})}>{draft.color===c&&<Check size={14}/>}</button>)}</fieldset>}</div>{error&&<p role="alert" className="inline-error">{error}</p>}<div className="modal-footer"><span><ShieldCheck size={14}/>Saved privately on this device</span><button type="button" className="secondary" onClick={close}>Cancel</button><button className="primary" type="submit" disabled={recording||acquiring||busy}>{busy?'Saving…':note.highlightOnly&&draft.highlight?'Save highlight':'Save thought'}<Check size={16}/></button></div></form></Modal>;
}

function AllNotes({docs,notes,onJump,onCite,onEdit,onDelete}){const [q,setQ]=useState(''),[docId,setDocId]=useState(''),[since,setSince]=useState('');const matched=notes.filter(n=>{const d=docs.find(d=>d.id===n.docId);return(!docId||n.docId===docId)&&(!since||n.createdAt>=since)&&[n.quote,n.comment,n.transcript,...n.tags,d?.title,d?.author,...(d?.tags||[])].join(' ').toLowerCase().includes(q.toLowerCase());}).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));return <div className="all-notes-view"><div className="section-eyebrow">YOUR IDEAS, IN ONE PLACE</div><h1>Threads of thought<span className="brand-dot">.</span></h1><p className="page-description">Revisit the questions and connections you left in the margins.</p><div className="filter-bar"><label className="search-input"><Search size={18}/><input aria-label="Search thoughts" placeholder="Search thoughts, quotations, authors, or tags…" value={q} onChange={e=>setQ(e.target.value)}/></label><select aria-label="Filter thoughts by document" value={docId} onChange={e=>setDocId(e.target.value)}><option value="">All documents</option>{docs.map(d=><option key={d.id} value={d.id}>{d.title}</option>)}</select><input aria-label="Thoughts created since" type="date" value={since} onChange={e=>setSince(e.target.value)}/><DownloadLink className="secondary" route={'/export'+(docId?'?docId='+docId:'')}><Download size={16}/>Export</DownloadLink></div><div className="thought-grid">{matched.map(n=><NoteCard key={n.id} note={n} doc={docs.find(d=>d.id===n.docId)} onJump={()=>onJump(n)} onCite={()=>onCite(n)} onEdit={()=>onEdit(n)} onDelete={()=>onDelete(n)} onTranscribed={()=>window.location.reload()} onError={e=>alert(e)}/>)}</div>{!matched.length&&<div className="large-empty"><Quote size={32}/><h2>{notes.length?'No thoughts match this search.':'Give your ideas a place to stay.'}</h2><p>Select a passage in a paper to capture your first thought.</p></div>}</div>;}

function Retrieval({docs,onJump,config,onSettings,onSaveConfig}){
  const [query,setQuery]=useState(''),[docIds,setDocIds]=useState([]),[include,setInclude]=useState(false),[messages,setMessages]=useState([]),[busy,setBusy]=useState(false),[error,setError]=useState(''),[providerConsent,setProviderConsent]=useState(false);const bottom=useRef();
  useEffect(()=>setProviderConsent(false),[config.endpoint,config.chatModel,config.embeddingModel,config.keyVersion]);
  useEffect(()=>{bottom.current?.scrollIntoView({behavior:'smooth'});},[messages,busy]);
  async function ask(text){if(!text.trim()||busy)return;if(browserStorage&&config.hasApiKey&&!providerConsent){setError('Allow sending selected material to your provider before using AI.');return;}setBusy(true);setError('');setMessages(ms=>[...ms,{role:'user',text}]);setQuery('');try{const r=await api('/chat',{method:'POST',body:{query:text,docIds,includeFullText:include,providerConsent}});setMessages(ms=>[...ms,{role:'assistant',...r}]);}catch(e){setError(e.message);}finally{setBusy(false);}}
  return <div className="retrieval-view"><div className="retrieval-header"><div><span className="section-eyebrow"><Sparkles size={14}/>YOUR OWN THINKING, WITH A LITTLE HELP</span><h1>Pick up a thread.</h1><p>Describe what you remember. Find the thought you left behind.</p></div><span className="private-pill"><ShieldCheck size={14}/>Your library is the source</span></div><AIConnection compact config={config} onSave={onSaveConfig} request={api}/><div className="retrieval-options"><div className="scope-label"><BookOpen size={16}/><span>Search in</span><details className="scope-select"><summary>{docIds.length?docIds.length+' selected documents':'Entire library'}<ChevronDown size={14}/></summary><div><label><input type="checkbox" checked={!docIds.length} onChange={()=>setDocIds([])}/>Entire library</label>{docs.map(d=><label key={d.id}><input type="checkbox" checked={docIds.includes(d.id)} onChange={e=>setDocIds(ids=>e.target.checked?[...ids,d.id]:ids.filter(id=>id!==d.id))}/>{d.title}</label>)}</div></details></div><label className="toggle-label"><input type="checkbox" checked={include} onChange={e=>setInclude(e.target.checked)}/>Include full document text</label></div><p className="provider-disclosure">{include?'Full-text mode: scoped document text, notes, and your question may be sent to your configured embedding provider; relevant passages go to the chat provider.':'Notes mode: your saved quotations, thoughts, transcripts, and question are sent to your configured provider for retrieval and interpretation when you search. Original PDFs and audio are not sent by this feature.'}</p>{browserStorage&&config.hasApiKey&&<label className="provider-consent"><input type="checkbox" checked={providerConsent} onChange={e=>setProviderConsent(e.target.checked)}/><span>I allow sending my question and selected notes{include?' and document text':''} to {new URL(config.endpoint).host} for this AI session. My library remains stored on this device.</span></label>}<div className="chat-scroll">{!messages.length&&<div className="retrieval-empty"><span className="sparkle-emblem"><Sparkles size={28}/></span><h2>Start with a memory.</h2><p>A half-remembered question. A point of disagreement.<br/>A connection you wanted to come back to.</p><div className="suggestions">{['Where did I question the authors’ evidence?','Find my thought about the sample size.','What did I note about security?','Compare my notes from these two papers.'].map(q=><button key={q} onClick={()=>ask(q)}>{q}<ArrowUpRight size={16}/></button>)}</div></div>}{messages.map((m,i)=><div className={'chat-message '+m.role} key={i}>{m.role==='user'?<p>{m.text}</p>:<><div className="assistant-label"><Sparkles size={17}/>From your library <span>{m.mode==='semantic'?'Embeddings + keywords':m.mode==='model'?'Model-based semantic retrieval':'Keyword retrieval'}</span></div>{m.message&&<p>{m.message}</p>}{m.warning&&<p className="inline-warning">{m.warning}</p>}{m.statements?.length>0&&<div className="ai-interpretation"><span className="content-label">AI INTERPRETATION</span>{m.statements.map((s,j)=><p key={j}>{s.text} {s.source_ids.map(id=><button className="citation-link" key={id} onClick={()=>onJump(m.evidence.find(e=>e.id===id))}>[{m.evidence.findIndex(e=>e.id===id)+1}]</button>)}</p>)}</div>}{m.evidence?.length>0?<div className="evidence-list"><div className="content-label">SAVED EVIDENCE · {m.evidence.length} SOURCES</div>{m.evidence.map((s,j)=><button className="evidence-card" key={s.id} onClick={()=>onJump(s)}><div className="evidence-source"><b>[{j+1}] {s.title}</b><span>{s.page?'PDF '+s.page+(s.label?' · printed '+s.label:''):'Document note'}<ArrowUpRight size={14}/></span></div>{s.kind==='document'&&<small>Full document passage · author’s words</small>}{s.quote&&<blockquote>{s.quote}</blockquote>}{s.comment&&<div><span className="content-label">MY ORIGINAL THOUGHT</span><p>{s.comment}</p></div>}{s.transcript&&<div><span className="content-label">MY TRANSCRIPT</span><p>{s.transcript}</p></div>}{s.audio&&!s.transcript&&<small>Audio is saved but not transcribed.</small>}</button>)}</div>:<p className="muted">No matching saved evidence. Nothing has been invented.</p>}</>}</div>)}{busy&&<div className="chat-busy"><LoaderCircle size={17} className="spin"/>Looking through your saved material…</div>}<div ref={bottom}/></div>{error&&<p className="inline-error" role="alert">{error}</p>}<form className="chat-composer" onSubmit={e=>{e.preventDefault();ask(query);}}><textarea aria-label="Ask your library" rows={2} placeholder="I remember having a thought about…" value={query} onChange={e=>setQuery(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();ask(query);}}}/><button className="primary" aria-label="Search saved thinking" disabled={busy||!query.trim()}><Send size={18}/></button></form><p className="chat-footnote">Your thoughts, the author’s words, and AI interpretations stay distinct. Every source opens the original passage.</p></div>;
}

function SettingsModal({config,onSave,onClose,onRestore}){const [draft,setDraft]=useState({...config}),[error,setError]=useState(''),[busy,setBusy]=useState(false),[done,setDone]=useState(false);const field=(key,label,placeholder,type='text')=><label className="field">{label}<input type={type} autoComplete="off" value={draft[key]||''} placeholder={placeholder} onChange={e=>{setDone(false);setDraft({...draft,[key]:e.target.value});}}/></label>;return <Modal wide title="Make this space yours" subtitle="Local settings, provider connections, and a safe copy of your thinking." onClose={onClose}>{browserStorage&&<DeviceStorage onForget={async()=>{await onSave({forgetKeys:true});setDraft(d=>({...d,apiKey:'',transcriptionKey:''}));}}/>}<AIConnection config={config} onSave={onSave} request={api}/><form onSubmit={async e=>{e.preventDefault();setBusy(true);setError('');try{const payload={transcriptionEndpoint:draft.transcriptionEndpoint||'',transcriptionModel:draft.transcriptionModel||''};if(draft.transcriptionKey)payload.transcriptionKey=draft.transcriptionKey;await onSave(payload);setDraft(d=>({...d,apiKey:'',transcriptionKey:''}));setDone(true);}catch(e){setError(e.message);}finally{setBusy(false);}}}><div className="settings-section"><h3><Mic size={18}/>Audio transcription</h3><p>{browserStorage?'Recordings always save on this device first. Use Transcribe recording and confirm sending that recording to your provider. Transcription is never automatic on this website.':'Saving a recording sends the audio to this provider only when a transcription model is configured. With no model, originals stay local and you can add a transcript manually.'}</p>{field('transcriptionEndpoint','Separate base endpoint (optional)','Uses the AI endpoint when blank')}{field('transcriptionKey','Separate API key (optional)',config.hasTranscriptionKey?'A key is available; blank keeps the saved setting.':'Uses AI key when blank','password')}{field('transcriptionModel','Transcription model',browserStorage?'Empty = transcription disabled':'Empty = no automatic transcription')}<button type="button" className="text-button" onClick={async()=>{await onSave({transcriptionKey:''});setDraft(d=>({...d,transcriptionKey:''}));}}>Use AI key for transcription</button></div><div className="privacy-note"><ShieldCheck size={20}/><div><strong>Know what leaves your device.</strong><p>Reading, annotation, ordinary search, export, and backup use no AI service. Retrieval sends scoped quotations, notes, and transcripts for semantic selection, then relevant evidence for interpretation. Full document text is included only with your explicit toggle. Transcription sends the selected recording. {browserStorage?'Your own API keys stay only in this tab’s memory and are cleared on reload or tab close. No shared key or cloud library is provided. Your chosen provider must permit browser requests.':'Keys live in the server’s data folder and are never returned to the browser.'}</p></div></div>{error&&<p role="alert" className="inline-error">{error}</p>}<div className="modal-footer"><span>{done?'Settings saved locally.':'Keys are excluded from library backups.'}</span><button className="primary" disabled={busy}>{busy?'Saving…':'Save transcription settings'}<Check size={16}/></button></div></form><div className="settings-section backup-section"><h3><Download size={18}/>Keep a complete copy</h3><p>Back up documents, notes, recordings, transcripts, and the reading workspace. {browserStorage?'Restore replaces this browser’s library and keeps a previous-library recovery copy in browser storage. Backups exclude API keys.':'Restore replaces the library and keeps a recovery copy on disk. Backups exclude API keys.'}</p><DownloadLink route="/backup" className="secondary"><Download size={16}/>Download library backup</DownloadLink><button className="text-button" onClick={onRestore}>Restore a backup…</button><small>{browserStorage?'Browser backup and restore support ZIPs up to 256 MB, with up to 256 MB uncompressed. A saved backup file can be moved to another device and restored there. The website cannot access arbitrary folders without your permission.':'Restore supports backup ZIPs up to 100 MB (1 GB uncompressed). Larger libraries can be backed up by copying the data folder while the app is stopped.'}</small></div><details className="shortcuts"><summary>Keyboard shortcuts</summary><p>Ctrl/Cmd + K — retrieve your thinking<br/>Ctrl/Cmd + F — search the current PDF<br/>Ctrl/Cmd + Shift + N — general document thought<br/>← / → — previous / next PDF page<br/>Escape — close a dialog</p></details></Modal>;}
function Metadata({doc,onSave,onDelete,onClose}){const [draft,setDraft]=useState({...doc}),[tags,setTags]=useState(doc.tags.join(', ')),[error,setError]=useState(''),[busy,setBusy]=useState(false);return <Modal wide title="Document details" subtitle="PDF metadata is a starting point. Review it before citing." onClose={onClose}><form onSubmit={async e=>{e.preventDefault();setBusy(true);try{await onSave({...draft,tags:splitTags(tags)});}catch(e){setError(e.message);setBusy(false);}}}><label className="field">Title<input required value={draft.title} onChange={e=>setDraft({...draft,title:e.target.value})}/></label><label className="field">Authors <small>Use Family, Given; Family, Given. Semicolons separate authors.</small><input value={draft.author} onChange={e=>setDraft({...draft,author:e.target.value})}/></label><div className="form-grid">{[['publication','Journal / publication'],['year','Year'],['publisher','Publisher'],['doi','DOI'],['volume','Volume'],['issue','Issue'],['pages','Publication page range'],['url','Source URL'],['accessed','Accessed date'],['collection','Collection']].map(([key,label])=><label className="field" key={key}>{label}<input value={draft[key]||''} onChange={e=>setDraft({...draft,[key]:e.target.value})}/></label>)}<label className="field">Source type<select value={draft.citationType||'article-journal'} onChange={e=>setDraft({...draft,citationType:e.target.value})}><option value="article-journal">Journal article</option><option value="paper-conference">Conference paper</option><option value="book">Book</option><option value="chapter">Book chapter</option><option value="report">Report</option><option value="webpage">Web page</option></select></label><label className="field">Tags<input value={tags} onChange={e=>setTags(e.target.value)} placeholder="Comma-separated tags"/></label></div><label className="review-checkbox"><input type="checkbox" checked={draft.reviewed} onChange={e=>setDraft({...draft,reviewed:e.target.checked})}/>I have reviewed these citation details.</label>{error&&<p role="alert" className="inline-error">{error}</p>}<div className="modal-footer"><button type="button" className="text-button danger" onClick={onDelete}><Trash2 size={15}/>Delete document</button><button type="button" className="secondary" onClick={onClose}>Cancel</button><button className="primary" disabled={busy}>Save details<Check size={16}/></button></div></form></Modal>;}
function Citation({doc,page,onClose,onReview}){const [value,setValue]=useState(null),[error,setError]=useState(''),[copied,setCopied]=useState(false);useEffect(()=>{api('/documents/'+doc.id+'/citation?page='+page).then(setValue).catch(e=>setError(e.message));},[doc.id,page]);return <Modal title="Cite this reading" subtitle="MLA · Citation Style Language / citeproc" onClose={onClose}>{error&&<p className="inline-error">{error}</p>}{value&&<>{(!value.reviewed||value.missing.length>0)&&<div className="inline-warning">{!value.reviewed?'Metadata has not been reviewed. ':''}{value.missing.length?'Missing: '+value.missing.join(', ')+'. ':''}<button className="text-button" onClick={onReview}>Review details</button></div>}<div className="citation-page-reference">{pageReference({page:value.pdfPage,pageLabel:value.pageLabel})}</div><label className="field">Works Cited<textarea readOnly rows={5} value={value.worksCited}/></label><label className="field">Suggested in-text citation<input readOnly value={value.inText}/></label><p className="muted">{value.pageLabel?`This PDF labels the selected page ${value.pageLabel}. The saved passage is on PDF page ${page}.`:`PDF page ${page} is its position in the file. This PDF supplies no printed page label, so the citation omits a printed locator. Check the printed page before adding one.`}</p><div className="modal-footer"><button className="secondary" onClick={onReview}>Edit source details</button><button className="primary" onClick={async()=>{await navigator.clipboard.writeText(value.worksCited+'\n'+value.inText);setCopied(true);}}>{copied?'Copied':'Copy citations'}<Check size={16}/></button></div></>}</Modal>;}
createRoot(document.getElementById('root')).render(<App/>);
